"Un voyage importé deux fois, des souvenirs remplacés : l’appli retrouve les copies en trop et les photos qui ne servent plus à rien, sur ce téléphone et sur le serveur.":"رحلة مستوردة مرتين، ذكريات مستبدلة: يجد التطبيق النسخ الزائدة والصور التي لم تعد مفيدة، على هذا الهاتف وعلى الخادم.",
"🔁 Chercher les doublons":"🔁 البحث عن النسخ المكررة",
"🔁 Doublons":"🔁 النسخ المكررة",
"Ces voyages existent en plusieurs exemplaires. On garde celui qui est partagé ou le plus complet, les copies en trop sont supprimées (leurs photos aussi, si elles ne servent pas ailleurs).":"هذه الرحلات موجودة بعدة نسخ. نحتفظ بالمشتركة أو الأكمل، وتُحذف النسخ الزائدة (وصورها أيضًا إن لم تُستخدم في مكان آخر).",
"On garde : créé le {0} · {1} souvenirs · {2} photos":"نحتفظ بـ: أُنشئت في {0} · {1} ذكريات · {2} صور",
"À supprimer : créé le {0} · {1} souvenirs · {2} photos":"للحذف: أُنشئت في {0} · {1} ذكريات · {2} صور",
"🗑 Supprimer les copies cochées":"🗑 حذف النسخ المحددة",
"Aucun voyage en double. 👍":"لا توجد رحلات مكررة. 👍",
"🧹 Photos qui ne servent plus":"🧹 صور لم تعد مستخدمة",
"Photos de souvenirs supprimés ou remplacés, restées sur ce téléphone ou sur le serveur. L’appli synchronise d’abord, puis ne retire que les photos qui ne sont dans aucune fiche. Sur le serveur, seules celles envoyées il y a plus de 3 jours partent (le temps que tous les téléphones aient synchronisé).":"صور ذكريات محذوفة أو مستبدلة بقيت على هذا الهاتف أو على الخادم. يزامن التطبيق أولًا، ثم لا يزيل إلا الصور غير الموجودة في أي بطاقة. على الخادم، لا تُحذف إلا الصور المرسلة منذ أكثر من 3 أيام (حتى تتزامن كل الهواتف).",
"🧹 Faire le ménage des photos":"🧹 تنظيف الصور",
"Supprimer {0} copie(s) de voyage, avec leurs fiches ? (pour tout le monde si la synchro est active)":"حذف {0} نسخة من الرحلة مع بطاقاتها؟ (للجميع إذا كانت المزامنة مفعّلة)",
