"🔒 Stockage protégé : le téléphone ne fera pas de ménage dans tes voyages et tes photos.":"🔒 تخزين محمي: لن يحذف الهاتف رحلاتك وصورك.",
"⚠️ Stockage non protégé : si le téléphone manque de place, il peut effacer les données de l’appli.":"⚠️ تخزين غير محمي: إذا امتلأ الهاتف قد يحذف بيانات التطبيق.",
"Sur iPhone : ajoute Vezoria à l’écran d’accueil (Safari → Partager → « Sur l’écran d’accueil ») et ouvre-la de là. Garde aussi une 💾 sauvegarde complète de temps en temps.":"على iPhone: أضف Vezoria إلى الشاشة الرئيسية (Safari ← مشاركة ← «إضافة إلى الشاشة الرئيسية») وافتحه من هناك. واحتفظ أيضًا بـ 💾 نسخة احتياطية كاملة من حين لآخر.",
"Installe Vezoria (Google Play ou « Installer l’appli ») et ouvre-la souvent : Android protège alors son stockage. Garde aussi une 💾 sauvegarde complète de temps en temps.":"ثبّت Vezoria (Google Play أو «تثبيت التطبيق») وافتحه كثيرًا: عندها يحمي Android مساحته. واحتفظ أيضًا بـ 💾 نسخة احتياطية كاملة من حين لآخر.",
"🧹 Libérer de la place":"🧹 تحرير مساحة",
"Pour les voyages terminés ({0}), les grandes photos déjà envoyées sur le serveur sont retirées de ce téléphone. Les vignettes restent : la grille et le film s’affichent toujours, et la grande photo revient du serveur, en version allégée, quand tu l’ouvres (il faut du réseau). Les photos pas encore envoyées ne sont jamais touchées.":"في الرحلات المنتهية ({0})، تُزال من هذا الهاتف الصور الكبيرة المرسلة مسبقًا إلى الخادم. تبقى الصور المصغّرة: تظل الشبكة والفيلم ظاهرين، وتعود الصورة الكبيرة من الخادم بنسخة أخف عند فتحها (يلزم اتصال). الصور غير المرسلة بعد لا تُمسّ أبدًا.",
"Retirer de ce téléphone les grandes photos des voyages terminés déjà sur le serveur ? Les vignettes restent, et chaque grande photo revient quand tu l’ouvres.":"إزالة الصور الكبيرة للرحلات المنتهية الموجودة على الخادم من هذا الهاتف؟ تبقى الصور المصغّرة، وتعود كل صورة كبيرة عند فتحها.",
"🧹 {0} / {1}…":"🧹 {0} / {1}…",
"✅ {0} grande(s) photo(s) retirée(s) de ce téléphone · {1} Mo libérés.":"✅ أُزيلت {0} صورة كبيرة من هذا الهاتف · تحرير {1} ميغابايت.",
"Rien à libérer pour le moment (photos pas encore envoyées, ou déjà libérées).":"لا شيء لتحريره الآن (صور لم تُرسل بعد أو حُرّرت مسبقًا).",
"Ton ami scanne le code de son téléphone avec l’appareil photo.":"يمسح صديقك رمز هاتفه بالكاميرا.",
"Safari → « Partager » → « Sur l’écran d’accueil »":"Safari ← «مشاركة» ← «إضافة إلى الشاشة الرئيسية»",
"📤 Envoyer les liens":"📤 إرسال الروابط",
"Suivre ce voyage dans l’appli":"تابع هذه الرحلة في التطبيق",
"Installe Vezoria, puis touche 👥 → « Suivre un voyage avec un code » et entre ce code :":"ثبّت Vezoria، ثم المس 👥 ← «متابعة رحلة برمز» وأدخل هذا الرمز:",
"Copie ce code :":"انسخ هذا الرمز:",
"Remonter en haut de la page":"العودة إلى الأعلى",
"⏸️ Pause de sécurité : beaucoup de photos envoyées d’un coup. L’envoi reprend tout seul dans {0} min.":"⏸️ استراحة أمان: أُرسل عدد كبير من الصور دفعة واحدة. يُستأنف الإرسال تلقائيًا بعد {0} دقيقة.",
"📦 Place photos de ce carnet pleine sur le serveur ({0} Go) : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 امتلأت مساحة صور دفتر الرحلات هذا على الخادم ({0} غيغابايت): تبقى الصور المتبقية على هذا الهاتف، ولا يضيع شيء.",
"📦 Place photos de ce carnet pleine sur le serveur : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 امتلأت مساحة صور دفتر الرحلات هذا على الخادم: تبقى الصور المتبقية على هذا الهاتف، ولا يضيع شيء.",
"📦 Le serveur photos est plein pour le moment : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 خادم الصور ممتلئ حاليًا: تبقى الصور المتبقية على هذا الهاتف، ولا يضيع شيء.",
"🔔 Notifications":"🔔 الإشعارات",
"Notifications : {0} non lue{1}":"الإشعارات: {0} غير مقروءة",
"Aucune notification pour l’instant.":"لا توجد إشعارات بعد.",
"Les notifications des 30 derniers jours restent ici, sur ce téléphone.":"تبقى إشعارات آخر 30 يومًا هنا، على هذا الهاتف.",
"Les notifications sont désactivées : active-les dans Plus → ⚙️ Réglages.":"الإشعارات متوقفة: فعّلها من المزيد ← ⚙️ الإعدادات.",
"🗑 Tout effacer":"🗑 مسح الكل",
"Effacer toutes les notifications de la cloche ?":"مسح كل إشعارات الجرس؟",
"⭐ Vezoria te plaît ?":"⭐ هل أعجبك Vezoria؟",
"Une note sur Google Play aide d’autres voyageurs à trouver l’appli, et m’encourage à continuer à l’améliorer. Ça prend 30 secondes. Merci 🙏":"تقييمك على Google Play يساعد مسافرين آخرين على إيجاد التطبيق، ويشجعني على مواصلة تحسينه. يستغرق 30 ثانية. شكرًا 🙏",
