"Supprimer ce commentaire ?":"حذف هذا التعليق؟",
"Masquer les commentaires et ❤️ de cette personne sur ce téléphone ?":"إخفاء تعليقات هذا الشخص و❤️ على هذا الهاتف؟",
"Bloquer {0} ?\n\nSes commentaires et ❤️ sont masqués pour tous tes abonnés et elle est retirée de la liste.\nPour l’empêcher aussi de voir tes souvenirs, touche ensuite « 🔁 Nouveau lien abonné » et renvoie le lien seulement aux personnes de ton choix.":"حظر {0}؟\n\nتُخفى تعليقاته و❤️ عن كل متابعيك ويُزال من القائمة.\nولمنعه أيضًا من رؤية ذكرياتك، المس بعد ذلك «🔁 رابط متابعة جديد» وأرسل الرابط فقط إلى من تختارهم.",
"Créer un nouveau lien abonné ?\n\nL’ancien lien ne marchera plus : plus personne ne voit tes souvenirs tant que tu n’as pas renvoyé le nouveau lien. Les ❤️ et commentaires passés sont effacés.":"إنشاء رابط متابعة جديد؟\n\nسيتوقف الرابط القديم عن العمل: لن يرى أحد ذكرياتك حتى ترسل الرابط الجديد. تُحذف ❤️ والتعليقات السابقة.",
"Pourquoi signales-tu ce contenu ? (contenu illicite, harcèlement, nudité, violence, autre…)":"لماذا تبلّغ عن هذا المحتوى؟ (محتوى غير قانوني، تحرّش، عُري، عنف، غير ذلك…)",
"🚩 Signaler cette publication":"🚩 الإبلاغ عن هذا المنشور",
