"Il n’y a encore rien à raconter : ajoute des souvenirs avec des photos et des lieux.":"لا شيء لروايته بعد: أضف ذكريات مع صور وأماكن.",
"Ta route est visible des abonnés":"مسارك ظاهر للمتابعين",
"Ta route est cachée aux abonnés":"مسارك مخفي عن المتابعين",
"Touche pour la cacher":"المس لإخفائه",
"Touche pour la montrer sur leur carte":"المس لإظهاره على خريطتهم",
"La route du voyage":"مسار الرحلة",
"Route visible des abonnés":"المسار ظاهر للمتابعين",
"Route masquée aux abonnés":"المسار مخفي عن المتابعين",
"Montrer ta route aux abonnés de ce voyage ?\n\nIls verront sur une carte le trajet enregistré par le suivi et ta dernière position (précision ≈ 100 m), avec l’heure.\nTu peux arrêter quand tu veux : la carte disparaît chez eux à la synchro suivante.\nTes compagnons choisissent chacun pour eux.":"إظهار مسارك لمتابعي هذه الرحلة؟\n\nسيرون على خريطة المسار الذي سجّله التتبّع وآخر موقع لك (بدقة ≈ 100 م)، مع الوقت.\nيمكنك الإيقاف متى شئت: تختفي الخريطة لديهم عند المزامنة التالية.\nكل رفيق يقرّر لنفسه.",
"Publier « {0} » pour des abonnés ?\n\nIls verront uniquement les souvenirs : photos, titres, lieux et récits. Le programme, les réservations, le budget et les documents restent privés.\nUn souvenir marqué « privé » n’est jamais publié.\nIls voient les photos en vignettes (taille réduite).\nTa position n’est jamais montrée, sauf si chaque voyageur l’active lui-même dans le suivi du voyage.\nIls pourront mettre des ❤️ et des commentaires.":"نشر «{0}» للمتابعين؟\n\nسيرون الذكريات فقط: الصور والعناوين والأماكن والحكايات. يبقى البرنامج والحجوزات والميزانية والمستندات خاصة.\nالذكرى المعلَّمة «خاصة» لا تُنشر أبدًا.\nيرون الصور مصغّرة (بحجم أصغر).\nلا يظهر موقعك أبدًا، إلا إذا فعّله كل مسافر بنفسه في تتبّع الرحلة.\nيمكنهم وضع ❤️ وتعليقات.",
