"Saisis un montant en monnaie locale : il est converti dans la devise du voyage, au taux du jour.":"أدخل مبلغًا بالعملة المحلية: يُحوَّل إلى عملة الرحلة بسعر اليوم.",
"En faire une dépense":"تحويله إلى مصروف",
"Choisis la devise du ticket dans la liste, puis touche Convertir.":"اختر عملة الإيصال من القائمة، ثم المس «تحويل».",
"touche Convertir":"المس «تحويل»",
"Saisis d’abord le montant.":"أدخل المبلغ أولًا.",
"Facultatif : sauvegarde en ligne de tous tes voyages, pour les retrouver sur ton autre téléphone ou ta tablette avec le même code. Hors connexion, tout reste sur le téléphone et part dès que le réseau revient.":"اختياري: نسخة احتياطية على الإنترنت لكل رحلاتك، لتجدها على هاتفك الآخر أو جهازك اللوحي بالرمز نفسه. من دون اتصال، يبقى كل شيء على الهاتف ويُرسل فور عودة الشبكة.",
"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"لمشاركة رحلة واحدة، لا حاجة لهذا: في الرحلة، المس «مشاركة». عندها تُخزَّن هذه الرحلة فقط على الخادم، وتبقى رحلاتك الأخرى على هاتفك.",
