"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"إنشاء رمز جديد لـ «{0}»؟\n\nتُرسل الرحلة وبطاقاتها وصورها مجددًا إلى الخادم تحت هذا الرمز الجديد. ثم على الهواتف الأخرى الانضمام بالرمز الجديد (رحلاتي ← الانضمام إلى رحلة مُشاركة).",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ تعذّر إرسال الرحلة تحت الرمز الجديد: {0}\nأعد المحاولة بـ «إعادة إرسال كل شيء» عندما يكون الاتصال جيدًا.",
"✅ Voyage en ligne : le code peut être donné":"✅ الرحلة على الإنترنت: يمكنك مشاركة الرمز",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"هل كان لهذه الرحلة رمز من قبل (حُذف من الخادم مثلًا)؟ الصقه هنا لإعادة استخدامه: ستجده الهواتف الأخرى مجددًا.\nوإلا فاتركه فارغًا: سيُنشأ رمز جديد.",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 حُذف من الخادم: {0} بطاقة و{1} صورة.\nتبقى بياناتك على هذا الهاتف.\n\nالاحتفاظ بالرمز على هذا الهاتف؟\nموافق = أحتفظ بالرمز: يمكنك إعادة إرسال كل شيء لاحقًا بالرمز نفسه (زر «إعادة إرسال كل شيء»).\nإلغاء = أنسى هذا الرمز هنا.",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"احتُفظ بالرمز. لإعادة كل شيء إلى الخادم: {0} ← «إعادة إرسال كل شيء».",
"Mes voyages → le voyage → code":"رحلاتي ← الرحلة ← الرمز",
"📤 Voyage ou photos non arrivés ?":"📤 لم تصل الرحلة أو الصور؟",
"Renvoie vers le serveur toutes les fiches et toutes les photos de ce téléphone, par exemple après une suppression sur le serveur. Rien n’est dupliqué.":"يعيد إرسال كل البطاقات وكل الصور الموجودة على هذا الهاتف إلى الخادم، مثلًا بعد حذف بياناتك منه. لا يتكرر شيء.",
"📤 Tout renvoyer":"📤 إعادة إرسال كل شيء",
"{0} fiche(s) et {1} photo(s) remises en file d’envoi.":"أُعيدت {0} بطاقة و{1} صورة إلى قائمة الإرسال.",
" · automatique toutes les heures":" · تلقائي كل ساعة",
"📌 Mes raccourcis":"📌 اختصاراتي",
"Épingle un écran pour qu’il apparaisse en haut de l’écran principal. Sans rien d’épinglé, cette barre n’apparaît pas. La barre du bas reste la même.":"ثبّت شاشة لتظهر أعلى الشاشة الرئيسية. إن لم تثبّت شيئًا، لا يظهر هذا الشريط. يبقى الشريط السفلي كما هو.",
