"👀 3 voyages de démo sont prêts (rien n’est partagé) :\n\n📍 En cours : on est au jour 7 — traceur, steps, tickets, courses, plafond, parts inégales.\n🧳 Préparation : le même Japon dans 6 mois, à organiser.\n🗺️ Passés / 🏁 Bilan : le voyage terminé avec ses photos, son album et ses comptes.\n\nPasse d’un onglet à l’autre en haut de l’écran. « Supprimer la démo » efface tout.":"👀 3 رحلات تجريبية جاهزة (لا شيء مُشارك):\n\n📍 جارية: نحن في اليوم 7 — التتبّع، الخطوات، الإيصالات، المشتريات، الحد اليومي، حصص غير متساوية.\n🧳 تحضير: رحلة اليابان نفسها بعد 6 أشهر، للتنظيم.\n🗺️ السابقة / 🏁 الحصيلة: الرحلة المنتهية بصورها وألبومها وحساباتها.\n\nتنقّل بين التبويبات في أعلى الشاشة. «حذف التجربة» يمحو كل شيء.",
