"🔗 Voyages partagés séparément":"🔗 رحلات مُشاركة بشكل منفصل",
"Un voyage peut avoir son propre code : seuls ceux qui l’ont le voient (par ex. Claire voit 2 voyages, Alex 1 seul). Ton code principal ci-dessous partage le reste.":"يمكن أن يكون لرحلة رمزها الخاص: لا يراها إلا من لديه الرمز (مثلًا Claire ترى رحلتين، وAlex رحلة واحدة). رمزك الرئيسي أدناه يشارك الباقي.",
"☁️ Carnet partagé (code principal)":"☁️ دفتر مُشارك (الرمز الرئيسي)",
"État :":"الحالة:",
"Dernière synchro : {0}":"آخر مزامنة: {0}",
"Code du carnet :":"رمز الدفتر:",
"Désactiver la synchro sur ce téléphone":"تعطيل المزامنة على هذا الهاتف",
"Une fois l’appli en ligne sur Cloudflare (voir le LISEZMOI), vous utilisez le même code : ce que l’un modifie, l’autre le voit. Hors connexion, tout reste enregistré sur le téléphone et part dès que le réseau revient.":"بعد نشر التطبيق على Cloudflare (انظر ملف README)، تستخدمون الرمز نفسه: ما يعدّله أحدكم يراه الآخرون. من دون اتصال، يُحفظ كل شيء على الهاتف ويُرسل فور عودة الشبكة.",
"Code du carnet":"رمز الدفتر",
"🎲 pour créer un nouveau carnet, ou colle le code reçu pour rejoindre.":"🎲 لإنشاء دفتر جديد، أو الصق الرمز الذي استلمته للانضمام.",
