"🎬 Tutos":"🎬 الدروس",
"Les 4 espaces du carnet (Préparation, En cours, Passés, Bilan), et l’essentiel pour bien commencer.":"مساحات الدفتر الأربع (التحضير، الجارية، السابقة، الحصيلة)، وأساسيات البدء.",
"et sur le serveur":"وعلى الخادم",
"🗑 Demander l’effacement sur le serveur":"🗑 طلب الحذف من الخادم",
"🕘 Activité récente":"🕘 النشاط الأخير",
"🗑 Mes données sur le serveur":"🗑 بياناتي على الخادم",
"Tu peux effacer à tout moment ton carnet du serveur (fiches et photos), pour toi et tes compagnons.":"يمكنك في أي وقت محو دفترك من الخادم (البطاقات والصور)، لك ولرفاقك.",
"🗑 Supprimer mes données du serveur":"🗑 حذف بياناتي من الخادم",
