"Tout est enregistré sur ce téléphone ({0} Ko){1}. L’export reste ta copie de secours, et il contient aussi l’archive 2026.":"كل شيء محفوظ على هذا الهاتف ({0} ك.ب){1}. يبقى التصدير نسختك الاحتياطية، ويحتوي أيضًا على أرشيف 2026.",
"💾 Sauvegarde complète ZIP (avec photos)":"💾 نسخة احتياطية كاملة ZIP (مع الصور)",
