"Effacer ce téléphone":"مسح هذا الهاتف",
"🔒 Mentions légales et confidentialité":"🔒 الإشعار القانوني والخصوصية",
"Choisis ou génère un code d’au moins 8 caractères.":"اختر أو أنشئ رمزًا من 8 أحرف على الأقل.",
"Indique l’adresse de l’appli en ligne.":"أدخل عنوان التطبيق على الإنترنت.",
"Le carnet partagé contient déjà {0} fiches.\n\nOK = utiliser le carnet partagé (recommandé pour rejoindre : ce téléphone garde seulement ses profils).\nAnnuler = fusionner les deux carnets.":"يحتوي الدفتر المُشارك بالفعل على {0} بطاقة.\n\nموافق = استخدام الدفتر المُشارك (موصى به للانضمام: يحتفظ هذا الهاتف بملفاته الشخصية فقط).\nإلغاء = دمج الدفترين.",
"☁️ Synchro activée":"☁️ المزامنة مفعّلة",
"Désactiver la synchro sur ce téléphone ? Les données restent ici.":"تعطيل المزامنة على هذا الهاتف؟ تبقى البيانات هنا.",
"Rejoins notre carnet de voyage 🧳\n{0}\nCode du carnet : {1}\n(⚙️ Partage → colle le code → Activer la synchro)":"انضم إلى دفتر رحلاتنا 🧳\n{0}\nرمز الدفتر: {1}\n(⚙️ المشاركة ← الصق الرمز ← تفعيل المزامنة)",
"📤 Export prêt":"📤 التصدير جاهز",
"Ce fichier ne contient pas de carnet de voyage.":"هذا الملف لا يحتوي على دفتر رحلات.",
"Le voyage 2027 existe déjà ici. Le remplacer par celui du fichier ?":"رحلة 2027 موجودة هنا بالفعل. استبدالها بتلك الموجودة في الملف؟",
"Fichier illisible : ce n’est pas un export JSON valide.":"ملف غير مقروء: ليس ملف تصدير JSON صالحًا.",
"Le fichier contient aussi l’archive 2026. La restaurer ?":"يحتوي الملف أيضًا على أرشيف 2026. استعادته؟",
"Ce carnet n’est pas synchronisé : rien n’est stocké sur le serveur.":"هذا الدفتر غير متزامن: لا شيء مخزّن على الخادم.",
"Demander l’effacement de ce carnet sur le serveur ?\n\nToutes ses données en ligne seront supprimées, pour TOUS ses membres. Un e-mail va être préparé : il contient seulement l’identifiant chiffré du carnet, jamais son code.":"طلب حذف هذا الدفتر من الخادم؟\n\nستُحذف كل بياناته على الإنترنت، لكل أعضائه. سيُجهَّز بريد إلكتروني: يحتوي فقط على المعرّف المشفّر للدفتر، وليس رمزه أبدًا.",
"Les données restent sur le serveur partagé, tu pourras le rejoindre à nouveau avec le code.":"تبقى البيانات على الخادم المُشارك، ويمكنك الانضمام مجددًا بالرمز.",
"Sans synchro, tout sera perdu : exporte avant !":"من دون مزامنة سيضيع كل شيء: صدّر أولًا!",
"Pour confirmer, écris EFFACER en majuscules :":"للتأكيد، اكتب EFFACER بأحرف كبيرة:",
