"Jusqu’au 31 décembre 2026, le premium est offert à tous":"حتى 31 ديسمبر 2026، الوضع المميز مجاني للجميع",
": rien à faire, tout est déjà débloqué. À partir du 1er janvier, il faudra la phrase d’accès ci-dessous.":": لا شيء عليك فعله، كل شيء مفتوح بالفعل. ابتداءً من 1 يناير، ستحتاج إلى عبارة الدخول أدناه.",
"✈️ Ouvrir Escale":"✈️ فتح Escale",
"🎓 Escale en mode premium":"🎓 Escale في الوضع المميز",
"🎬 La vidéo (3 min) montre tout le parcours sur un voyage fictif Paris → Tokyo : menu, passage en premium, dates, calendrier de prix, prix live, hôtels, voiture, activités, puis la saisie dans le carnet. Le détail écrit est juste en dessous.":"🎬 يعرض الفيديو (3 دقائق) المسار كاملًا على رحلة خيالية باريس ← طوكيو: القائمة، الانتقال إلى المميز، التواريخ، تقويم الأسعار، الأسعار المباشرة، الفنادق، السيارة، الأنشطة، ثم الإدخال في الدفتر. التفاصيل المكتوبة أدناه مباشرة.",
"Escale cherche les vols les moins chers. En":"يبحث Escale عن أرخص رحلات الطيران. في",
"mode soft":"الوضع الخفيف",
"(par défaut), les prix viennent d’un cache gratuit : ce sont des":"(الافتراضي)، تأتي الأسعار من ذاكرة مؤقتة مجانية: إنها",
"prix indicatifs":"أسعار استرشادية",
"mode premium":"الوضع المميز",
"interroge les sources en direct.":"يستعلم المصادر مباشرة.",
"1. Passer en premium":"1. الانتقال إلى المميز",
