"« ◐ Mode SOFT · appuyer pour PREMIUM »":"«◐ Mode SOFT · appuyer pour PREMIUM»",
"sous le titre (ou menu":"تحت العنوان (أو القائمة",
"☰ → Réglages → Changer de mode":"☰ → Réglages → Changer de mode",
"). Saisis la phrase d’accès : l’appli se recharge et affiche":"). أدخل عبارة الدخول: يُعاد تحميل التطبيق ويعرض",
"« ● Mode PREMIUM »":"«● Mode PREMIUM»",
"La":"إن",
