"au premium t’est donnée par la personne qui t’a invité sur l’appli. Elle ne se trouve pas dans le carnet.":"إلى المميز يعطيك إياها من دعاك إلى التطبيق. وهي غير موجودة في الدفتر.",
"2. Ce que le premium débloque":"2. ما يفتحه المميز",
