"montre chaque jour, du moins cher (vert) au plus cher (rouge). Un jour vert entouré = vol direct. Puis touche":"يعرض كل يوم، من الأرخص (أخضر) إلى الأغلى (أحمر). يوم أخضر محاط بدائرة = رحلة مباشرة. ثم المس",
