", ouvre le vol et remplis la compagnie, les horaires, le prix et le lien de réservation. Le budget et « qui doit quoi » se mettent à jour tout seuls.":"، افتح الرحلة واملأ شركة الطيران والمواعيد والسعر ورابط الحجز. تتحدّث الميزانية و«من يدين بماذا» تلقائيًا.",
"💡 Le premium utilise des services payants à quota : garde-le pour tes vraies dates, et repasse en soft pour flâner.":"💡 يستخدم المميز خدمات مدفوعة بحصص محدودة: احتفظ به لتواريخك الحقيقية، وعُد إلى الخفيف للتصفّح.",
