"Ordres de grandeur (distance à vol d’oiseau corrigée × facteurs moyens type ADEME), pas un calcul certifié. Conseils de réservation = tendances générales, pas une prédiction de prix.":"تقديرات تقريبية (مسافة الخط المستقيم المصحّحة × عوامل متوسطة على طريقة ADEME)، وليست حسابًا معتمدًا. نصائح الحجز = اتجاهات عامة، لا توقّع للأسعار.",
