"📲 Installer maintenant":"📲 التثبيت الآن",
"Ensuite, ouvre toujours l’appli depuis son icône. Le navigateur et l’appli installée ne partagent pas leurs données : crée ou rejoins ton carnet depuis l’icône.":"من الآن، افتح التطبيق دائمًا من أيقونته. المتصفح والتطبيق المثبّت لا يتشاركان بياناتهما: أنشئ دفترك أو انضم إليه من الأيقونة.",
