"Devise proposée pour les nouveaux voyages. Un voyage déjà créé garde la sienne : change-la en modifiant le voyage.":"العملة المقترحة للرحلات الجديدة. تحتفظ الرحلة الموجودة بعملتها: غيّرها بتعديل الرحلة.",
"Saisis un montant en monnaie locale, l’appli le convertit dans la devise du voyage (aussi dans chaque fiche, sous « Prix réel »).":"أدخل مبلغًا بالعملة المحلية، ويحوّله التطبيق إلى عملة الرحلة (وأيضًا داخل كل بطاقة، تحت «السعر الفعلي»).",
