"Quelqu’un":"شخص ما",
"Sur iPhone, les notifications marchent quand Vezoria est ajoutée à l’écran d’accueil (Partager → « Sur l’écran d’accueil »), avec iOS 16.4 ou plus récent.":"على iPhone، تعمل الإشعارات عندما يُضاف Vezoria إلى الشاشة الرئيسية (مشاركة ← «إضافة إلى الشاشة الرئيسية»)، مع iOS 16.4 أو أحدث.",
"Ce navigateur ne sait pas recevoir de notifications.":"هذا المتصفح لا يستطيع استقبال الإشعارات.",
"Notifications refusées. Pour les autoriser : réglages du téléphone → Notifications → Vezoria.":"تم رفض الإشعارات. للسماح بها: إعدادات الهاتف ← الإشعارات ← Vezoria.",
