"Notifications":"الإشعارات",
"Les notifications sont bloquées pour Vezoria dans les réglages du téléphone. Autorise-les, puis reviens ici.":"إشعارات Vezoria محظورة في إعدادات الهاتف. اسمح بها ثم عد إلى هنا.",
