"Le contenu des notifications est chiffré : le serveur ne peut pas le lire. Tes compagnons choisissent les leurs.":"محتوى الإشعارات مشفّر: لا يستطيع الخادم قراءته. رفاقك يختارون إشعاراتهم بأنفسهم.",
"Le contenu des notifications est chiffré : le serveur ne peut pas le lire. Tes compagnons choisissent les leurs. Pour être prévenu des ajouts de tes compagnons, partage d’abord un voyage.":"محتوى الإشعارات مشفّر: لا يستطيع الخادم قراءته. رفاقك يختارون إشعاراتهم بأنفسهم. لتعرف ما يضيفه رفاقك، شارك رحلة أولًا.",
"Mode trajet":"وضع التنقّل",
"Écran allumé, GPS précis : pour une route, un train, une rando":"شاشة مضاءة وGPS دقيق: لرحلة بالسيارة أو القطار أو نزهة مشي",
"Ce téléphone ne peut pas garder l’écran allumé : désactive la mise en veille automatique le temps du trajet.":"لا يستطيع هذا الهاتف إبقاء الشاشة مضاءة: أوقف القفل التلقائي طوال الرحلة.",
