"Garde Vezoria ouverte au premier plan, téléphone branché de préférence : ta route s’enregistre tous les 50 m environ. Touche l’écran pour l’assombrir.":"أبقِ Vezoria مفتوحًا في الواجهة، ويُفضّل أن يكون الهاتف موصولًا بالشاحن: يُسجَّل مسارك كل 50 م تقريبًا. المس الشاشة لتعتيمها.",
"Terminer le mode trajet":"إنهاء وضع التنقّل",
"Cartes hors ligne":"خرائط بلا إنترنت",
"Rues, lieux à voir, hôtels et ta position sur une carte zoomable, même sans réseau ni données à l’étranger. À télécharger en Wi-Fi avant de partir.":"الشوارع والأماكن والفنادق وموقعك على خريطة قابلة للتكبير، حتى بلا شبكة أو بيانات في الخارج. نزّلها عبر Wi-Fi قبل السفر.",
"Recherche des étapes…":"جارٍ البحث عن المحطات…",
"Rues, lieux à voir, hôtels et ta position, même sans réseau ni données à l’étranger. À télécharger en Wi-Fi avant le départ.":"الشوارع والأماكن والفنادق وموقعك، حتى بلا شبكة أو بيانات في الخارج. نزّلها عبر Wi-Fi قبل السفر.",
