"⚠️ {0} morceaux non téléchargés (réseau ?). Réessaie en Wi-Fi.":"⚠️ لم تُنزَّل {0} قطعة (الشبكة؟). أعد المحاولة عبر Wi-Fi.",
"✅ Cartes prêtes : elles marchent maintenant sans réseau.":"✅ الخرائط جاهزة: تعمل الآن بلا شبكة.",
"Effacer les cartes hors ligne de ce téléphone ?":"حذف الخرائط غير المتصلة من هذا الهاتف؟",
