"Choisis ce fichier ici (ou le fichier trip.json d’un voyage).":"اختر هذا الملف هنا (أو ملف trip.json لرحلة).",
"Tes étapes, lieux, récits et photos deviennent des souvenirs Vezoria. Tout se passe sur ton téléphone : le fichier n’est envoyé nulle part. Vezoria n’est pas lié à Polarsteps.":"تصبح محطاتك وأماكنك وقصصك وصورك ذكريات في Vezoria. كل شيء يتم على هاتفك: لا يُرسَل الملف إلى أي مكان. Vezoria غير مرتبط بـ Polarsteps.",
