"Chutes en avril-mai pour le débit, éléphants de Chobe en bateau, mokoro dans le delta de l’Okavango.":"الشلالات في أبريل ومايو لغزارتها، أفيال تشوبي بالقارب، قارب الموكورو في دلتا أوكافانغو.",
"Randonnées vertigineuses de Santo Antão, morna et bars de Mindelo, ferry entre les îles.":"مسارات مذهلة في سانتو أنتاو، موسيقى المورنا وحانات منديلو، عبّارات بين الجزر.",
"Ruelles bleues de Chefchaouen tôt le matin, cascades d’Akchour, médina de Tanger.":"أزقة شفشاون الزرقاء صباحاً باكراً، شلالات أقشور، مدينة طنجة العتيقة.",
"Aurores à Abisko (ciel souvent clair), traîneau à chiens, Icehotel de Jukkasjärvi.":"الشفق القطبي في أبيسكو (سماء صافية غالباً)، زلاجات الكلاب، فندق الجليد في يوكاسيارفي.",
"Cyclades plus calmes que Santorin, villages de Naxos en voiture, Naoussa le soir.":"جزر سيكلادس أهدأ من سانتوريني، قرى ناكسوس بالسيارة، ناوسا مساءً.",
"Col des Nuages à moto, Hội An aux lanternes, cité impériale de Hué.":"ممر هاي فان بالدراجة النارية، فوانيس هوي آن، المدينة الإمبراطورية في هوي.",
"Nuit sur une jonque dans la baie de Lan Ha (plus calme), rizières de Sa Pa, vieux quartier de Hanoï.":"ليلة على مركب شراعي في خليج لان ها (أهدأ)، مدرجات الأرز في سا با، الحي القديم في هانوي.",
"Mont Royal, Vieux-Montréal, festivals d’été (jazz, Juste pour rire), poutine et bagels.":"جبل مونت رويال، مونتريال القديمة، مهرجانات الصيف (الجاز، جوست بور ريغ)، البوتين والبيغل.",
"Angels Landing (permis), Bryce au lever du soleil, Delicate Arch au coucher du soleil.":"آنجلز لاندينغ (بتصريح)، برايس عند الشروق، القوس الرقيق عند الغروب.",
"Perito Moreno, randonnée au Fitz Roy depuis El Chaltén, canal de Beagle à Ushuaïa.":"بيريتو مورينو، مسار فيتز روي من إل تشالتين، قناة بيغل من أوشوايا.",
"Dunes de Maspalomas, Roque Nublo, plage de Las Canteras en ville.":"كثبان ماسبالوماس، روكي نوبلو، شاطئ لاس كانتيراس في المدينة.",
