"Pot commun des photos (bêta)":"مخزن الصور المشترك (تجريبي)",
"Chaque photo est rangée une seule fois sur le serveur et partagée par un lien secret : tes compagnons et tes abonnés voient la vraie photo, en grand, sans copie en plus.":"تُحفظ كل صورة مرة واحدة على الخادم وتُشارك برابط سري: يرى رفاقك ومتابعوك الصورة الحقيقية بالحجم الكامل دون نسخة إضافية.",
