"Ajoute au moins 2 visites par ville pour avoir un conseil.":"أضف زيارتين على الأقل لكل مدينة للحصول على نصيحة.",
"Ce jour-là tu es à {0}":"في ذلك اليوم ستكون في {0}",
"Chaque journée suit l’ordre du trajet, de proche en proche. Tu peux encore tout déplacer dans le programme.":"كل يوم يتبع ترتيب المسار، من مكان إلى أقرب مكان. لا يزال بإمكانك نقل كل شيء في البرنامج.",
