"Rien n’est figé : si tu choisis un hôtel ailleurs, mets son adresse dans l’hébergement puis « Réorganiser depuis mon hôtel ». Les journées repartiront de là.":"لا شيء نهائي: إذا اخترت فندقًا في مكان آخر، أضف عنوانه إلى الإقامة ثم «إعادة التنظيم من فندقي». ستبدأ الأيام من هناك.",
