"Si l’auteur a perdu son lien (changement de téléphone…), il l’ouvre : l’appli lui rend ses abonnés.":"إذا فقد صاحب الرحلة رابطه (تغيير الهاتف…) يفتحه فيعيد له التطبيق متابعيه.",
